with feeders as (
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , cast(null as varchar) as PREMIUM_HEAD_CODE
        , cast(null as varchar) as SECTION
        , PREM_BASE_COVER as BASE_AMOUNT
        , cast(null as varchar) as PREMIUM_BASIS
        , cast(null as varchar) as NET_HEAD_PREMIUM
        , 'BA_HCP_DT_MEM' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_dt_mem') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__POLICY_NO))) as HUB_POLICY_HK
        , cast(null as varchar) as PREMIUM_HEAD_CODE
        , cast(null as varchar) as SECTION
        , cast(null as varchar) as BASE_AMOUNT
        , PER_PERSON_PREM_TYPE as PREMIUM_BASIS
        , cast(null as varchar) as NET_HEAD_PREMIUM
        , 'BJAZ_GRP_HLT_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_grp_hlt_dtls') }}
    where (nullif(trim(POLICY_NO),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__REG_NO))) as HUB_POLICY_HK
        , cast(null as varchar) as PREMIUM_HEAD_CODE
        , cast(null as varchar) as SECTION
        , PRIME_RIDER_BASE_PREM as BASE_AMOUNT
        , cast(null as varchar) as PREMIUM_BASIS
        , PERMIUM_CO_BUFFER as NET_HEAD_PREMIUM
        , 'BJAZ_GRP_HLT_MATERNITY_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_grp_hlt_maternity_dtls') }}
    where (nullif(trim(REG_NO),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , cast(null as varchar) as PREMIUM_HEAD_CODE
        , cast(null as varchar) as SECTION
        , cast(null as varchar) as BASE_AMOUNT
        , cast(null as varchar) as PREMIUM_BASIS
        , FLOAT_PREMIUM as NET_HEAD_PREMIUM
        , 'BJAZ_HCF_MEMBER_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcf_member_dtls') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__POLICY_REF))) as HUB_POLICY_HK
        , cast(null as varchar) as PREMIUM_HEAD_CODE
        , cast(null as varchar) as SECTION
        , SURG_COVER_BASE_PREM as BASE_AMOUNT
        , cast(null as varchar) as PREMIUM_BASIS
        , cast(null as varchar) as NET_HEAD_PREMIUM
        , 'BJAZ_HEALTH_WEBSERVICE_INFO' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_health_webservice_info') }}
    where (nullif(trim(POLICY_REF),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , 'BURGJWEL' as PREMIUM_HEAD_CODE
        , 'SEC2' as SECTION
        , cast(null as varchar) as BASE_AMOUNT
        , cast(null as varchar) as PREMIUM_BASIS
        , SEC2_BURGJWEL_PREM as NET_HEAD_PREMIUM
        , 'BA_CCP_SUB_MATER_DTLS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ba_ccp_sub_mater_dtls') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
),

resolved as (
    select
        HUB_POLICY_HK,
        PREMIUM_HEAD_CODE,
        SECTION,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then BASE_AMOUNT end) as BASE_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PREMIUM_BASIS end) as PREMIUM_BASIS,
        coalesce(max(case when SOURCE_RUN = 'opus_health_legacy_v4' then NET_HEAD_PREMIUM end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then NET_HEAD_PREMIUM end)) as NET_HEAD_PREMIUM,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_POLICY_HK, PREMIUM_HEAD_CODE, SECTION
),

hashed as (
    select
        *,
        case when PREMIUM_HEAD_CODE is not null or SECTION is not null or BASE_AMOUNT is not null or PREMIUM_BASIS is not null or NET_HEAD_PREMIUM is not null
                     then md5(upper(coalesce(cast(PREMIUM_HEAD_CODE as varchar), '') || '|' || coalesce(cast(SECTION as varchar), '') || '|' || coalesce(cast(BASE_AMOUNT as varchar), '') || '|' || coalesce(cast(PREMIUM_BASIS as varchar), '') || '|' || coalesce(cast(NET_HEAD_PREMIUM as varchar), '')))
                end as SAT_POLICY_PREMIUM_HEAD_HASHDIFF
    from resolved
)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_PREMIUM_HEAD_HASHDIFF is not null
